BEGIN;

INSERT INTO bai_doc (course_id, slug, title_vi, title_zh, passage_zh, pinyin, translation_vi, est_minutes, is_published)
SELECT c.id, r.slug, r.title_vi, r.title_zh, r.passage_zh, r.pinyin, r.translation_vi, r.est_minutes, true
FROM (VALUES
  ('hsk-1', 'hsk1-gia-dinh-nho', 'Gia đình nhỏ', '我的小家', '我家有三口人。爸爸、妈妈和我。我们晚上一起吃饭。', 'Wǒ jiā yǒu sān kǒu rén. Bàba, māma hé wǒ. Wǒmen wǎnshang yìqǐ chīfàn.', 'Nhà tôi có ba người: bố, mẹ và tôi. Buổi tối chúng tôi ăn cơm cùng nhau.', 3),
  ('hsk-1', 'hsk1-nguoi-ban-moi', 'Người bạn mới', '新朋友', '我的朋友叫小美。她是学生。我们在学校一起学习。', 'Wǒ de péngyou jiào Xiǎo Měi. Tā shì xuésheng. Wǒmen zài xuéxiào yìqǐ xuéxí.', 'Bạn tôi tên là Tiểu Mỹ. Bạn ấy là học sinh. Chúng tôi cùng học ở trường.', 3),
  ('hsk-1', 'hsk1-di-hoc-bang-xe-buyt', 'Đi học bằng xe buýt', '坐公共汽车上学', '今天我坐公共汽车去学校。车上有很多人。我八点到学校。', 'Jīntiān wǒ zuò gōnggòng qìchē qù xuéxiào. Chē shàng yǒu hěn duō rén. Wǒ bā diǎn dào xuéxiào.', 'Hôm nay tôi đi xe buýt đến trường. Trên xe có nhiều người. Tôi đến trường lúc tám giờ.', 3),
  ('hsk-1', 'hsk1-mua-trai-cay', 'Mua trái cây', '买水果', '妈妈买了苹果和香蕉。苹果十块钱，香蕉五块钱。我们回家吃水果。', 'Māma mǎi le píngguǒ hé xiāngjiāo. Píngguǒ shí kuài qián, xiāngjiāo wǔ kuài qián. Wǒmen huí jiā chī shuǐguǒ.', 'Mẹ mua táo và chuối. Táo giá mười tệ, chuối giá năm tệ. Chúng tôi về nhà ăn trái cây.', 3),
  ('hsk-1', 'hsk1-thoi-tiet-dep', 'Thời tiết đẹp', '天气很好', '今天不冷，也不热。天气很好。我们想去公园。', 'Jīntiān bù lěng, yě bú rè. Tiānqì hěn hǎo. Wǒmen xiǎng qù gōngyuán.', 'Hôm nay không lạnh cũng không nóng. Thời tiết rất đẹp. Chúng tôi muốn đi công viên.', 3),
  ('hsk-1', 'hsk1-mon-an-yeu-thich', 'Món ăn yêu thích', '喜欢的菜', '我喜欢吃米饭和鸡蛋。弟弟喜欢喝牛奶。我们都不喜欢吃辣的菜。', 'Wǒ xǐhuan chī mǐfàn hé jīdàn. Dìdi xǐhuan hē niúnǎi. Wǒmen dōu bù xǐhuan chī là de cài.', 'Tôi thích ăn cơm và trứng. Em trai thích uống sữa. Chúng tôi đều không thích món cay.', 3),
  ('hsk-1', 'hsk1-phong-cua-toi', 'Phòng của tôi', '我的房间', '我的房间有一张桌子和两把椅子。桌子上有书和水杯。我的房间很干净。', 'Wǒ de fángjiān yǒu yì zhāng zhuōzi hé liǎng bǎ yǐzi. Zhuōzi shàng yǒu shū hé shuǐbēi. Wǒ de fángjiān hěn gānjìng.', 'Phòng tôi có một chiếc bàn và hai chiếc ghế. Trên bàn có sách và cốc nước. Phòng tôi rất sạch sẽ.', 3),
  ('hsk-1', 'hsk1-thu-bay', 'Ngày thứ Bảy', '星期六', '星期六我没有课。我上午看书，下午和朋友踢足球。晚上我们在家看电视。', 'Xīngqīliù wǒ méiyǒu kè. Wǒ shàngwǔ kàn shū, xiàwǔ hé péngyou tī zúqiú. Wǎnshang wǒmen zài jiā kàn diànshì.', 'Thứ Bảy tôi không có tiết học. Buổi sáng tôi đọc sách, buổi chiều đá bóng với bạn. Buổi tối chúng tôi xem tivi ở nhà.', 3),
  ('hsk-1', 'hsk1-mot-ngay-cua-toi', 'Một ngày của tôi', '我的一天', '我早上六点起床，七点吃早饭。下午三点回家，晚上十点睡觉。', 'Wǒ zǎoshang liù diǎn qǐchuáng, qī diǎn chī zǎofàn. Xiàwǔ sān diǎn huí jiā, wǎnshang shí diǎn shuìjiào.', 'Tôi thức dậy lúc sáu giờ sáng và ăn sáng lúc bảy giờ. Ba giờ chiều tôi về nhà, mười giờ tối tôi đi ngủ.', 3),

  ('hsk-2', 'hsk2-ngan-hang-va-sieu-thi', 'Ngân hàng và siêu thị', '银行和超市', '我今天先去银行，然后去超市买东西。超市离银行不远，走路十分钟就到。', 'Wǒ jīntiān xiān qù yínháng, ránhòu qù chāoshì mǎi dōngxi. Chāoshì lí yínháng bù yuǎn, zǒulù shí fēnzhōng jiù dào.', 'Hôm nay tôi đến ngân hàng trước, sau đó đi siêu thị mua đồ. Siêu thị không xa ngân hàng, đi bộ mười phút là tới.', 4),
  ('hsk-2', 'hsk2-hang-xom-moi', 'Người hàng xóm mới', '新邻居', '新邻居刚搬到我们楼上。他们家有一个小女孩。昨天我送给她一本中文书。', 'Xīn línjū gāng bān dào wǒmen lóu shàng. Tāmen jiā yǒu yí ge xiǎo nǚhái. Zuótiān wǒ sòng gěi tā yì běn Zhōngwén shū.', 'Người hàng xóm mới vừa chuyển đến tầng trên nhà tôi. Gia đình họ có một bé gái. Hôm qua tôi tặng bé một quyển sách tiếng Trung.', 4),
  ('hsk-2', 'hsk2-cuoi-tuan-mua-mua', 'Cuối tuần mưa', '下雨的周末', '上个周末一直下雨，所以我们没有去爬山。朋友带来几部电影，我们在家看了一下午，觉得也很开心。', 'Shàng ge zhōumò yìzhí xià yǔ, suǒyǐ wǒmen méiyǒu qù pá shān. Péngyou dài lái jǐ bù diànyǐng, wǒmen zài jiā kàn le yí xiàwǔ, juéde yě hěn kāixīn.', 'Cuối tuần trước trời mưa suốt nên chúng tôi không đi leo núi. Bạn mang đến vài bộ phim, chúng tôi xem ở nhà cả buổi chiều và vẫn thấy rất vui.', 4),
  ('hsk-2', 'hsk2-hoc-nau-an', 'Học nấu ăn', '学做饭', '我以前不太会做饭。最近我跟姐姐学做中国菜。她说先把菜洗干净，再切成小块。', 'Wǒ yǐqián bú tài huì zuò fàn. Zuìjìn wǒ gēn jiějie xué zuò Zhōngguó cài. Tā shuō xiān bǎ cài xǐ gānjìng, zài qiē chéng xiǎo kuài.', 'Trước đây tôi không biết nấu ăn lắm. Gần đây tôi học nấu món Trung Quốc với chị gái. Chị nói trước tiên rửa rau sạch rồi cắt thành miếng nhỏ.', 4),
  ('hsk-2', 'hsk2-tham-ba', 'Thăm bà', '去看奶奶', '每个月我都会去奶奶家看她。她喜欢听我说学校的事情，我也帮她买菜、整理房间。', 'Měi ge yuè wǒ dōu huì qù nǎinai jiā kàn tā. Tā xǐhuan tīng wǒ shuō xuéxiào de shìqing, wǒ yě bāng tā mǎi cài, zhěnglǐ fángjiān.', 'Tháng nào tôi cũng đến thăm bà. Bà thích nghe tôi kể chuyện ở trường, còn tôi giúp bà mua rau và dọn phòng.', 4),
  ('hsk-2', 'hsk2-tim-dien-thoai', 'Tìm điện thoại', '找手机', '昨天我在公共汽车上找不到手机，后来发现它在书包的小口袋里。以后我会先检查口袋再出门。', 'Zuótiān wǒ zài gōnggòng qìchē shàng zhǎo bú dào shǒujī, hòulái fāxiàn tā zài shūbāo de xiǎo kǒudài lǐ. Yǐhòu wǒ huì xiān jiǎnchá kǒudài zài chūmén.', 'Hôm qua tôi không tìm thấy điện thoại trên xe buýt, sau đó mới phát hiện nó ở ngăn nhỏ trong ba lô. Từ nay tôi sẽ kiểm tra túi trước khi ra ngoài.', 4),
  ('hsk-2', 'hsk2-di-bien-mua-he', 'Ra biển mùa hè', '暑假去海边', '我们打算暑假坐火车去海边。妈妈已经买好了车票，我负责准备水和水果。', 'Wǒmen dǎsuàn shǔjià zuò huǒchē qù hǎibiān. Māma yǐjīng mǎi hǎo le chēpiào, wǒ fùzé zhǔnbèi shuǐ hé shuǐguǒ.', 'Chúng tôi dự định đi tàu hỏa ra biển vào kỳ nghỉ hè. Mẹ đã mua vé, còn tôi phụ trách chuẩn bị nước và trái cây.', 4),
  ('hsk-2', 'hsk2-mua-sach-buoi-toi', 'Mua sách buổi tối', '晚上买书', '这家书店周末常常很忙。店员告诉我，晚上七点以后人少一些，我就选择下班后去买书。', 'Zhè jiā shūdiàn zhōumò chángcháng hěn máng. Diànyuán gàosu wǒ, wǎnshang qī diǎn yǐhòu rén shǎo yìxiē, wǒ jiù xuǎnzé xiàbān hòu qù mǎi shū.', 'Hiệu sách này thường rất đông vào cuối tuần. Nhân viên nói sau bảy giờ tối sẽ vắng hơn nên tôi chọn ghé mua sách sau giờ làm.', 4),
  ('hsk-2', 'hsk2-di-bo-sau-bua-toi', 'Đi bộ sau bữa tối', '晚饭后散步', '医生建议我每天走路半小时。我现在晚饭后和爸爸散步，有时候还一起练习中文。', 'Yīshēng jiànyì wǒ měitiān zǒulù bàn xiǎoshí. Wǒ xiànzài wǎnfàn hòu hé bàba sànbù, yǒushíhou hái yìqǐ liànxí Zhōngwén.', 'Bác sĩ khuyên tôi đi bộ nửa giờ mỗi ngày. Bây giờ tôi đi dạo với bố sau bữa tối, đôi khi chúng tôi còn cùng luyện tiếng Trung.', 4),

  ('hsk-3', 'hsk3-thu-vien-cuoi-tuan', 'Cuối tuần ở thư viện', '周末的图书馆', '社区图书馆最近延长了开放时间。为了准备考试，我每周六上午都去那里复习。安静的环境让我更容易集中注意力。', 'Shèqū túshūguǎn zuìjìn yáncháng le kāifàng shíjiān. Wèile zhǔnbèi kǎoshì, wǒ měi zhōuliù shàngwǔ dōu qù nàli fùxí. Ānjìng de huánjìng ràng wǒ gèng róngyì jízhōng zhùyìlì.', 'Thư viện cộng đồng gần đây kéo dài giờ mở cửa. Để chuẩn bị cho kỳ thi, sáng thứ Bảy nào tôi cũng đến đó ôn tập. Không gian yên tĩnh giúp tôi tập trung hơn.', 5),
  ('hsk-3', 'hsk3-sua-xe-dap', 'Sửa chiếc xe đạp', '修自行车', '我的自行车坏了，车轮一直发出奇怪的声音。我本来想买一辆新的，邻居却教我换轮胎。修好以后，它骑起来和以前一样轻快。', 'Wǒ de zìxíngchē huài le, chēlún yìzhí fāchū qíguài de shēngyīn. Wǒ běnlái xiǎng mǎi yí liàng xīn de, línjū què jiāo wǒ huàn lúntāi. Xiū hǎo yǐhòu, tā qí qǐlái hé yǐqián yíyàng qīngkuài.', 'Xe đạp của tôi bị hỏng, bánh xe phát ra tiếng lạ. Ban đầu tôi định mua xe mới, nhưng người hàng xóm đã dạy tôi thay lốp. Sửa xong, xe chạy nhẹ nhàng như trước.', 5),
  ('hsk-3', 'hsk3-chon-thanh-pho-nho', 'Chọn một thành phố nhỏ', '选择小城市', '毕业以后，林涛没有留在大城市，而是回到家乡工作。虽然工资没有那么高，但他离父母很近，也有更多时间做自己喜欢的事。', 'Bìyè yǐhòu, Lín Tāo méiyǒu liú zài dà chéngshì, ér shì huí dào jiāxiāng gōngzuò. Suīrán gōngzī méiyǒu nàme gāo, dàn tā lí fùmǔ hěn jìn, yě yǒu gèng duō shíjiān zuò zìjǐ xǐhuan de shì.', 'Sau khi tốt nghiệp, Lâm Đào không ở lại thành phố lớn mà trở về quê làm việc. Tuy lương không cao bằng, anh ở gần bố mẹ và có thêm thời gian làm điều mình thích.', 5),
  ('hsk-3', 'hsk3-du-an-nhom', 'Dự án nhóm', '小组项目', '老师让我们四个人组成一组，调查校园里的垃圾分类情况。我们分工收集资料、设计问卷，再把结果做成图表。合作让任务比想象中完成得更快。', 'Lǎoshī ràng wǒmen sì ge rén zǔchéng yì zǔ, diàochá xiàoyuán lǐ de lājī fēnlèi qíngkuàng. Wǒmen fēngōng shōují zīliào, shèjì wènjuàn, zài bǎ jiéguǒ zuò chéng túbiǎo. Hézuò ràng rènwu bǐ xiǎngxiàng zhōng wánchéng de gèng kuài.', 'Thầy giáo chia bốn người chúng tôi thành một nhóm để khảo sát việc phân loại rác trong trường. Chúng tôi chia nhau thu thập thông tin, thiết kế khảo sát rồi trình bày kết quả bằng biểu đồ. Làm việc chung giúp hoàn thành nhanh hơn dự tính.', 5),
  ('hsk-3', 'hsk3-doi-tra-hang', 'Đổi trả hàng', '退换商品', '我在网上买了一件外套，收到以后发现袖子太长。客服建议我先申请换货，再把商品寄回去。虽然多等了几天，最后还是换到了合适的尺寸。', 'Wǒ zài wǎngshàng mǎi le yí jiàn wàitào, shōudào yǐhòu fāxiàn xiùzi tài cháng. Kèfú jiànyì wǒ xiān shēnqǐng huànhuò, zài bǎ shāngpǐn jì huíqù. Suīrán duō děng le jǐ tiān, zuìhòu háishi huàn dào le héshì de chǐcùn.', 'Tôi mua một chiếc áo khoác trên mạng, khi nhận mới thấy tay áo quá dài. Nhân viên hỗ trợ khuyên tôi đăng ký đổi hàng rồi gửi sản phẩm lại. Dù phải chờ thêm vài ngày, cuối cùng tôi cũng đổi được kích cỡ phù hợp.', 5),
  ('hsk-3', 'hsk3-tap-the-duc-buoi-sang', 'Tập thể dục buổi sáng', '早晨锻炼', '刚搬到新小区时，我不认识附近的人。后来我每天早晨去广场跑步，慢慢认识了几位邻居。现在我们常常约好一起锻炼，身体也比以前健康。', 'Gāng bān dào xīn xiǎoqū shí, wǒ bù rènshi fùjìn de rén. Hòulái wǒ měitiān zǎochén qù guǎngchǎng pǎobù, mànmàn rènshi le jǐ wèi línjū. Xiànzài wǒmen chángcháng yuē hǎo yìqǐ duànliàn, shēntǐ yě bǐ yǐqián jiànkāng.', 'Khi mới chuyển đến khu nhà mới, tôi không quen ai quanh đó. Sau này sáng nào tôi cũng chạy ở quảng trường và dần quen vài người hàng xóm. Giờ chúng tôi thường hẹn nhau tập thể dục, sức khỏe cũng tốt hơn trước.', 5),
  ('hsk-3', 'hsk3-le-hoi-van-hoa', 'Lễ hội văn hóa', '文化节', '学校举办文化节时，每个班都准备了一个节目。我们介绍家乡的传统食物，还请同学们一起包饺子。活动结束后，很多外国学生说他们更了解中国家庭的生活了。', 'Xuéxiào jǔbàn wénhuàjié shí, měi ge bān dōu zhǔnbèi le yí ge jiémù. Wǒmen jièshào jiāxiāng de chuántǒng shíwù, hái qǐng tóngxuémen yìqǐ bāo jiǎozi. Huódòng jiéshù hòu, hěn duō wàiguó xuésheng shuō tāmen gèng liǎojiě Zhōngguó jiātíng de shēnghuó le.', 'Khi trường tổ chức lễ hội văn hóa, mỗi lớp đều chuẩn bị một tiết mục. Chúng tôi giới thiệu món ăn truyền thống quê nhà và mời các bạn cùng gói bánh chẻo. Sau chương trình, nhiều sinh viên nước ngoài nói rằng họ hiểu hơn về cuộc sống gia đình Trung Quốc.', 5),
  ('hsk-3', 'hsk3-hoc-ngoai-ngu', 'Học ngoại ngữ', '学习外语', '刚开始学中文时，我常常把相似的发音弄错。老师没有让我着急，而是建议我每天听十分钟录音，再大声跟读。坚持几个月以后，我发现自己听懂的内容越来越多。', 'Gāng kāishǐ xué Zhōngwén shí, wǒ chángcháng bǎ xiāngsì de fāyīn nòng cuò. Lǎoshī méiyǒu ràng wǒ zháojí, ér shì jiànyì wǒ měitiān tīng shí fēnzhōng lùyīn, zài dàshēng gēndú. Jiānchí jǐ ge yuè yǐhòu, wǒ fāxiàn zìjǐ tīng dǒng de nèiróng yuèláiyuè duō.', 'Khi mới học tiếng Trung, tôi thường nhầm những âm gần giống nhau. Thầy không làm tôi lo lắng mà khuyên mỗi ngày nghe ghi âm mười phút rồi đọc theo thành tiếng. Kiên trì vài tháng, tôi nhận ra mình nghe hiểu ngày càng nhiều.', 5),
  ('hsk-3', 'hsk3-vuon-rau-cong-dong', 'Vườn rau cộng đồng', '社区菜园', '公寓楼下有一块空地，居民们决定把它改成菜园。大家轮流浇水、除草，收获以后再把蔬菜分给老人。这个小花园让邻居之间更加熟悉。', 'Gōngyù lóu xià yǒu yí kuài kòngdì, jūmínmen juédìng bǎ tā gǎi chéng càiyuán. Dàjiā lúnyì jiāoshuǐ, chú cǎo, shōuhuò yǐhòu zài bǎ shūcài fēn gěi lǎorén. Zhège xiǎo huāyuán ràng línjū zhījiān gèngjiā shúxī.', 'Có một khoảng đất trống dưới tòa chung cư, cư dân quyết định biến nơi đó thành vườn rau. Mọi người thay phiên tưới cây, nhổ cỏ rồi chia rau thu hoạch cho người lớn tuổi. Khu vườn nhỏ khiến hàng xóm thân thiết hơn.', 5),

  ('hsk-4', 'hsk4-giao-thong-cong-cong', 'Giao thông công cộng', '公共交通', '为了缓解早晚高峰的拥堵，市政府增加了地铁班次，并在几个主要路口设置了公交专用道。虽然这些措施不能立刻解决所有问题，但通勤时间已经明显缩短。', 'Wèile huǎnjiě zǎowǎn gāofēng de yōngdǔ, shì zhèngfǔ zēngjiā le dìtiě bāncì, bìng zài jǐ ge zhǔyào lùkǒu shèzhì le gōngjiāo zhuānyòngdào. Suīrán zhèxiē cuòshī bùnéng lìkè jiějué suǒyǒu wèntí, dàn tōngqín shíjiān yǐjīng míngxiǎn suōduǎn.', 'Để giảm ùn tắc giờ cao điểm sáng tối, chính quyền tăng chuyến tàu điện ngầm và bố trí làn xe buýt riêng ở một số giao lộ chính. Những biện pháp này chưa thể giải quyết mọi vấn đề ngay lập tức, nhưng thời gian đi làm đã rút ngắn rõ rệt.', 7),
  ('hsk-4', 'hsk4-lam-viec-tu-xa', 'Làm việc từ xa', '远程办公', '远程办公给员工带来了更大的灵活性，也减少了每天往返公司的时间。不过，如果团队缺少清楚的沟通规则，重要信息就容易被遗漏。因此，企业需要同时改善工具和管理方式。', 'Yuǎnchéng bàngōng gěi yuángōng dài lái le gèng dà de línghuóxìng, yě jiǎnshǎo le měitiān wǎngfǎn gōngsī de shíjiān. Búguò, rúguǒ tuánduì quēshǎo qīngchu de gōutōng guīzé, zhòngyào xìnxī jiù róngyì bèi yílòu. Yīncǐ, qǐyè xūyào tóngshí gǎishàn gōngjù hé guǎnlǐ fāngshì.', 'Làm việc từ xa giúp nhân viên linh hoạt hơn và giảm thời gian đi lại mỗi ngày. Tuy nhiên, nếu nhóm thiếu quy tắc trao đổi rõ ràng, thông tin quan trọng dễ bị bỏ sót. Vì vậy, doanh nghiệp cần cải thiện cả công cụ lẫn cách quản lý.', 7),
  ('hsk-4', 'hsk4-an-toan-khi-di-bo', 'An toàn khi đi bộ đường dài', '徒步安全', '第一次参加长途徒步时，周明带了很多不必要的东西，却忘记准备足够的水。领队提醒大家，出发前应该查看天气、规划路线，并把急救用品放在容易拿到的地方。', 'Dì yī cì cānjiā chángtú túbù shí, Zhōu Míng dài le hěn duō bù bìyào de dōngxi, què wàngjì zhǔnbèi zúgòu de shuǐ. Lǐngduì tíxǐng dàjiā, chūfā qián yīnggāi chákàn tiānqì, guīhuà lùxiàn, bìng bǎ jíjiù yòngpǐn fàng zài róngyì ná dào de dìfang.', 'Lần đầu đi bộ đường dài, Chu Minh mang nhiều đồ không cần thiết nhưng lại quên chuẩn bị đủ nước. Trưởng đoàn nhắc mọi người nên xem thời tiết, lên kế hoạch tuyến đường và để dụng cụ sơ cứu ở nơi dễ lấy trước khi khởi hành.', 7),
  ('hsk-4', 'hsk4-can-bang-dinh-duong', 'Cân bằng dinh dưỡng', '均衡饮食', '营养师指出，健康饮食并不意味着完全放弃自己喜欢的食物，而是要注意种类和分量。多吃蔬菜、适量摄入蛋白质，再配合规律运动，往往比短期节食更容易坚持。', 'Yíngyǎngshī zhǐchū, jiànkāng yǐnshí bìng bù yìwèizhe wánquán fàngqì zìjǐ xǐhuan de shíwù, ér shì yào zhùyì zhǒnglèi hé fènliàng. Duō chī shūcài, shìliàng shèrù dànbáizhì, zài pèihé guīlǜ yùndòng, wǎngwǎng bǐ duǎnqī jiéshí gèng róngyì jiānchí.', 'Chuyên gia dinh dưỡng cho biết ăn uống lành mạnh không có nghĩa phải từ bỏ hoàn toàn món mình thích, mà cần chú ý sự đa dạng và khẩu phần. Ăn nhiều rau, bổ sung protein vừa phải và vận động đều đặn thường dễ duy trì hơn ăn kiêng ngắn hạn.', 7),
  ('hsk-4', 'hsk4-bao-ve-di-san', 'Bảo vệ di sản', '保护文化遗产', '老城区的一座古桥曾经面临拆除，因为附近的道路需要扩建。居民和历史学者提出了新的设计方案，最终让桥梁得以保留，同时也改善了交通。这个结果说明，发展与保护并非总是互相冲突。', 'Lǎo chéngqū de yí zuò gǔqiáo céngjīng miànlín chāichú, yīnwèi fùjìn de dàolù xūyào kuòjiàn. Jūmín hé lìshǐ xuézhě tíchū le xīn de shèjì fāngàn, zuìzhōng ràng qiáoliáng déyǐ bǎoliú, tóngshí yě gǎishàn le jiāotōng. Zhège jiéguǒ shuōmíng, fāzhǎn yǔ bǎohù bìngfēi zǒng shì hùxiāng chōngtū.', 'Một cây cầu cổ ở khu phố cũ từng đứng trước nguy cơ bị phá bỏ vì con đường gần đó cần mở rộng. Cư dân và các nhà nghiên cứu lịch sử đề xuất phương án thiết kế mới, cuối cùng vừa giữ được cây cầu vừa cải thiện giao thông. Kết quả cho thấy phát triển và bảo tồn không phải lúc nào cũng đối lập.', 7),
  ('hsk-4', 'hsk4-mua-sam-than-thien', 'Mua sắm thân thiện môi trường', '环保购物', '越来越多的商店开始减少一次性包装，并鼓励顾客自带购物袋。刚开始，有些人觉得这样不方便；习惯以后，他们却发现准备一个布袋并不麻烦，还能减少塑料垃圾。', 'Yuèláiyuè duō de shāngdiàn kāishǐ jiǎnshǎo yícìxìng bāozhuāng, bìng gǔlì gùkè zì dài gòuwùdài. Gāng kāishǐ, yǒuxiē rén juéde zhèyàng bù fāngbiàn; xíguàn yǐhòu, tāmen què fāxiàn zhǔnbèi yí ge bùdài bìng bù máfan, hái néng jiǎnshǎo sùliào lājī.', 'Ngày càng nhiều cửa hàng giảm bao bì dùng một lần và khuyến khích khách tự mang túi. Ban đầu có người thấy bất tiện, nhưng khi quen rồi, họ nhận ra chuẩn bị một chiếc túi vải không khó mà còn giảm được rác nhựa.', 7),
  ('hsk-4', 'hsk4-giao-tiep-trong-nhom', 'Giao tiếp trong nhóm', '团队沟通', '项目进度落后时，组员之间开始互相埋怨。负责人没有立刻追究责任，而是先和大家一起找出问题所在，再重新分配任务。明确的分工和定期汇报让合作逐渐恢复顺利。', 'Xiàngmù jìndù luòhòu shí, zǔyuán zhījiān kāishǐ hùxiāng mányuàn. Fùzérén méiyǒu lìkè zhuījiū zérèn, ér shì xiān hé dàjiā yìqǐ zhǎo chū wèntí suǒzài, zài chóngxīn fēnpèi rènwu. Míngquè de fēngōng hé dìngqī huìbào ràng hézuò zhújiàn huīfù shùnlì.', 'Khi tiến độ dự án chậm lại, các thành viên bắt đầu trách móc lẫn nhau. Người phụ trách không vội quy trách nhiệm mà cùng mọi người tìm nguyên nhân rồi phân công lại. Vai trò rõ ràng và báo cáo định kỳ giúp việc hợp tác dần trở lại thuận lợi.', 7),
  ('hsk-4', 'hsk4-tham-quan-bao-tang', 'Tham quan bảo tàng', '参观博物馆', '这家博物馆为每件展品提供了语音介绍，游客可以按照自己的速度参观。小林原本只打算停留一个小时，听完几个故事后却在里面待了一整个下午。', 'Zhè jiā bówùguǎn wèi měi jiàn zhǎnpǐn tígōng le yǔyīn jièshào, yóukè kěyǐ ànzhào zìjǐ de sùdù cānguān. Xiǎo Lín yuánběn zhǐ dǎsuàn tíngliú yí ge xiǎoshí, tīng wán jǐ ge gùshi hòu què zài lǐmiàn dāi le yí zhěng ge xiàwǔ.', 'Bảo tàng này có phần thuyết minh âm thanh cho mỗi hiện vật để khách tham quan theo tốc độ riêng. Tiểu Lâm ban đầu chỉ định ở lại một giờ, nhưng sau khi nghe vài câu chuyện đã dành cả buổi chiều ở đó.', 7),
  ('hsk-4', 'hsk4-quan-ly-thoi-gian', 'Quản lý thời gian', '管理时间', '以前我总是把任务留到最后一天，结果常常熬夜完成。后来我把大目标拆成每天可以完成的小步骤，并在日历上安排休息时间。这样做以后，我的工作质量和睡眠都改善了。', 'Yǐqián wǒ zǒngshì bǎ rènwu liú dào zuìhòu yì tiān, jiéguǒ chángcháng áoyè wánchéng. Hòulái wǒ bǎ dà mùbiāo chāi chéng měitiān kěyǐ wánchéng de xiǎo bùzhòu, bìng zài rìlì shàng ānpái xiūxi shíjiān. Zhèyàng zuò yǐhòu, wǒ de gōngzuò zhìliàng hé shuìmián dōu gǎishàn le.', 'Trước đây tôi thường để công việc đến ngày cuối cùng nên phải thức khuya hoàn thành. Sau đó tôi chia mục tiêu lớn thành những bước nhỏ mỗi ngày và xếp cả thời gian nghỉ vào lịch. Nhờ vậy, chất lượng công việc và giấc ngủ đều được cải thiện.', 7),

  ('hsk-5', 'hsk5-thu-vien-so', 'Thư viện số', '数字图书馆', '数字图书馆让读者不必亲自前往，也能查阅大量资料。可是，信息数量增加并不代表判断能力自然提高。读者仍然需要核实来源、比较观点，并注意保护个人隐私。', 'Shùzì túshūguǎn ràng dúzhě búbì qīnzì qiánwǎng, yě néng cháyuè dàliàng zīliào. Kěshì, xìnxī shùliàng zēngjiā bìng bù dàibiǎo pànduàn nénglì zìrán tígāo. Dúzhě réngrán xūyào héshí láiyuán, bǐjiào guāndiǎn, bìng zhùyì bǎohù gèrén yǐnsī.', 'Thư viện số giúp độc giả tra cứu nhiều tài liệu mà không cần trực tiếp đến nơi. Tuy nhiên, lượng thông tin tăng không đồng nghĩa năng lực đánh giá tự nhiên tốt hơn. Người đọc vẫn cần kiểm tra nguồn, so sánh quan điểm và bảo vệ quyền riêng tư.', 8),
  ('hsk-5', 'hsk5-nghe-thuat-dan-gian', 'Nghệ thuật dân gian', '民间艺术', '一位年轻的木雕师回到家乡后，开始记录当地老人掌握的传统技法。他没有把作品原样复制，而是将古老图案融入日常用品。这样既保留了文化记忆，也让更多年轻人愿意接触这门手艺。', 'Yí wèi niánqīng de mùdiāoshī huí dào jiāxiāng hòu, kāishǐ jìlù dāngdì lǎorén zhǎngwò de chuántǒng jìfǎ. Tā méiyǒu bǎ zuòpǐn yuányàng fùzhì, ér shì jiāng gǔlǎo tú àn róngrù rìcháng yòngpǐn. Zhèyàng jì bǎoliú le wénhuà jìyì, yě ràng gèng duō niánqīng rén yuànyì jiēchù zhè mén shǒuyì.', 'Sau khi trở về quê, một nghệ nhân chạm khắc trẻ bắt đầu ghi lại kỹ thuật truyền thống mà người cao tuổi địa phương nắm giữ. Anh không sao chép nguyên mẫu mà đưa hoa văn cổ vào vật dụng thường ngày. Cách làm này vừa giữ ký ức văn hóa, vừa khiến người trẻ quan tâm đến nghề thủ công.', 8),
  ('hsk-5', 'hsk5-du-lich-cham', 'Du lịch chậm', '慢旅行', '与其在短时间内赶往许多景点，不如选择一个地方多住几天。游客可以观察当地人的生活节奏，也更容易发现旅游指南没有介绍的小店和街道。旅行的价值有时不在于去了多少地方，而在于真正理解了什么。', 'Yǔqí zài duǎn shíjiān nèi gǎnwǎng xǔduō jǐngdiǎn, bùrú xuǎnzé yí ge dìfang duō zhù jǐ tiān. Yóukè kěyǐ guānchá dāngdì rén de shēnghuó jiézòu, yě gèng róngyì fāxiàn lǚyóu zhǐnán méiyǒu jièshào de xiǎodiàn hé jiēdào. Lǚxíng de jiàzhí yǒushí bù zài yú qù le duōshǎo dìfang, ér zài yú zhēnzhèng lǐjiě le shénme.', 'Thay vì vội đến thật nhiều điểm trong thời gian ngắn, ta có thể chọn một nơi và ở lại vài ngày. Du khách sẽ quan sát được nhịp sống địa phương và dễ tìm thấy những cửa tiệm, con phố không có trong cẩm nang. Giá trị chuyến đi đôi khi không nằm ở số nơi đã đến mà ở điều ta thực sự hiểu được.', 8),
  ('hsk-5', 'hsk5-phan-hoi-khach-hang', 'Lắng nghe khách hàng', '倾听顾客', '公司过去只根据销售数字判断产品是否成功，忽略了顾客使用时遇到的困难。后来，团队定期邀请用户试用新功能，并认真记录意见。改进后的版本未必增加了所有功能，却解决了几个最常见的问题。', 'Gōngsī guòqù zhǐ gēnjù xiāoshòu shùzì pànduàn chǎnpǐn shìfǒu chénggōng, hūlüè le gùkè shǐyòng shí yùdào de kùnnan. Hòulái, tuánduì dìngqī yāoqǐng yònghù shìyòng xīn gōngnéng, bìng rènzhēn jìlù yìjiàn. Gǎijìn hòu de bǎnběn wèibì zēngjiā le suǒyǒu gōngnéng, què jiějué le jǐ ge zuì chángjiàn de wèntí.', 'Trước đây công ty chỉ dựa vào doanh số để đánh giá sản phẩm thành công hay không, bỏ qua khó khăn của khách hàng khi sử dụng. Sau đó, nhóm thường xuyên mời người dùng thử tính năng mới và ghi nhận ý kiến nghiêm túc. Phiên bản cải tiến không nhất thiết có thêm mọi chức năng, nhưng giải quyết được vài vấn đề phổ biến nhất.', 8),
  ('hsk-5', 'hsk5-thoi-quen-doc-sach', 'Thói quen đọc sâu', '深入阅读', '每天接触大量短消息，使人能够迅速了解发生了什么，却未必有时间思考事情为什么发生。为了改变这种状态，陈雨每天留出半小时读一本长篇作品，并把触动自己的句子记下来。几个月后，她发现自己表达观点时更有条理。', 'Měitiān jiēchù dàliàng duǎn xiāoxi, shǐ rén nénggòu xùnsù liǎojiě fāshēng le shénme, què wèibì yǒu shíjiān sīkǎo shìqing wèishénme fāshēng. Wèile gǎibiàn zhè zhǒng zhuàngtài, Chén Yǔ měitiān liú chū bàn xiǎoshí dú yì běn chángpiān zuòpǐn, bìng bǎ chùdòng zìjǐ de jùzi jì xiàlái. Jǐ ge yuè hòu, tā fāxiàn zìjǐ biǎodá guāndiǎn shí gèng yǒu tiáolǐ.', 'Tiếp xúc nhiều tin nhắn ngắn mỗi ngày giúp ta nhanh biết chuyện gì đang xảy ra, nhưng chưa chắc có thời gian suy nghĩ vì sao. Để thay đổi, Trần Vũ dành nửa giờ mỗi ngày đọc một tác phẩm dài và ghi lại những câu khiến mình xúc động. Vài tháng sau, cô thấy mình trình bày ý kiến mạch lạc hơn.', 8),
  ('hsk-5', 'hsk5-lua-chon-nghe-nghiep', 'Lựa chọn nghề nghiệp', '职业选择', '父母希望女儿找一份稳定的工作，她却想进入刚起步的环保企业。经过几次认真交谈，双方发现分歧并非来自目标不同，而是对风险的看法不同。女儿于是列出计划和备用方案，让家人了解自己已经考虑过可能的困难。', 'Fùmǔ xīwàng nǚér zhǎo yí fèn wěndìng de gōngzuò, tā què xiǎng jìnrù gāng qǐbù de huánbǎo qǐyè. Jīngguò jǐ cì rènzhēn jiāotán, shuāngfāng fāxiàn fēnqí bìngfēi láizì mùbiāo bùtóng, ér shì duì fēngxiǎn de kànfǎ bùtóng. Nǚér yúshì liè chū jìhuà hé bèiyòng fāngàn, ràng jiārén liǎojiě zìjǐ yǐjīng kǎolǜ guò kěnéng de kùnnan.', 'Bố mẹ mong con gái tìm một công việc ổn định, còn cô muốn vào một doanh nghiệp môi trường mới thành lập. Sau vài cuộc trò chuyện nghiêm túc, cả hai nhận ra bất đồng không phải do mục tiêu khác nhau mà do cách nhìn rủi ro. Cô gái liệt kê kế hoạch và phương án dự phòng để gia đình biết mình đã cân nhắc những khó khăn có thể xảy ra.', 8),
  ('hsk-5', 'hsk5-cong-vien-do-thi', 'Công viên đô thị', '城市公园', '一座废弃工厂改建成公园后，周围居民有了散步和运动的空间。设计者保留了部分旧机器，并在旁边说明它们曾经承担的功能。新旧元素同时存在，使参观者既能休息，也能了解城市发展的历史。', 'Yí zuò fèiqì gōngchǎng gǎijiàn chéng gōngyuán hòu, zhōuwéi jūmín yǒu le sànbù hé yùndòng de kōngjiān. Shèjìzhě bǎoliú le bùfen jiù jīqì, bìng zài pángbiān shuōmíng tāmen céngjīng chéngdān de gōngnéng. Xīn jiù yuánsù tóngshí cúnzài, shǐ cānguānzhě jì néng xiūxi, yě néng liǎojiě chéngshì fāzhǎn de lìshǐ.', 'Sau khi một nhà máy bỏ hoang được cải tạo thành công viên, cư dân quanh đó có không gian đi dạo và tập thể dục. Nhà thiết kế giữ lại một số máy móc cũ và chú thích chức năng trước đây của chúng. Sự hiện diện đồng thời của yếu tố cũ và mới giúp khách vừa nghỉ ngơi vừa hiểu lịch sử phát triển đô thị.', 8),
  ('hsk-5', 'hsk5-hoc-tu-that-bai', 'Học từ thất bại', '从失败中学习', '第一次创业失败以后，王磊很长时间不愿意谈起那段经历。后来他把每项支出和决定重新整理，发现自己过分依赖单一客户，也没有留下足够的周转资金。总结这些教训并不代表失败变得容易接受，却让下一次选择更加谨慎。', 'Dì yī cì chuàngyè shībài yǐhòu, Wáng Lěi hěn cháng shíjiān bù yuànyì tán qǐ nà duàn jīnglì. Hòulái tā bǎ měi xiàng zhīchū hé juédìng chóngxīn zhěnglǐ, fāxiàn zìjǐ guòfèn yīlài dānyī kèhù, yě méiyǒu liú xià zúgòu de zhōuzhuǎn zījīn. Zǒngjié zhèxiē jiàoxun bìng bù dàibiǎo shībài biàn de róngyì jiēshòu, què ràng xià yí cì xuǎnzé gèngjiā jǐnshèn.', 'Sau lần khởi nghiệp đầu tiên thất bại, Vương Lỗi không muốn nhắc đến trải nghiệm ấy trong thời gian dài. Sau đó anh xem lại từng khoản chi và quyết định, nhận ra mình phụ thuộc quá nhiều vào một khách hàng và không để đủ vốn lưu động. Tổng kết bài học không làm thất bại dễ chấp nhận hơn, nhưng giúp lựa chọn lần sau thận trọng hơn.', 8),
  ('hsk-5', 'hsk5-bao-ve-du-lieu-ca-nhan', 'Bảo vệ dữ liệu cá nhân', '保护个人数据', '便利的线上服务往往要求用户提供位置、联系人或消费记录。很多人为了快速完成注册，习惯直接同意所有权限，却很少查看资料会被保存多久。专家建议只提供必要信息，并定期检查应用程序的授权设置。', 'Biànlì de xiànshàng fúwù wǎngwǎng yāoqiú yònghù tígōng wèizhì, liánxìrén huò xiāofèi jìlù. Hěn duō rén wèile kuàisù wánchéng zhùcè, xíguàn zhíjiē tóngyì suǒyǒu quánxiàn, què hěn shǎo chákàn zīliào huì bèi bǎocún duōjiǔ. Zhuānjiā jiànyì zhǐ tígōng bìyào xìnxī, bìng dìngqī jiǎnchá yìngyòng chéngxù de shòuquán shèzhì.', 'Dịch vụ trực tuyến tiện lợi thường yêu cầu người dùng cung cấp vị trí, danh bạ hoặc lịch sử mua sắm. Để đăng ký nhanh, nhiều người có thói quen đồng ý mọi quyền truy cập nhưng ít xem dữ liệu được lưu bao lâu. Chuyên gia khuyên chỉ cung cấp thông tin cần thiết và thường xuyên kiểm tra quyền của ứng dụng.', 8),

  ('hsk-6', 'hsk6-cong-nghe-va-sang-tao', 'Công nghệ và sáng tạo', '技术与创造', '自动化工具能够承担重复而精确的工作，却不一定能理解任务背后的社会意义。真正有效的创新，往往来自技术人员与使用者持续交流。只有把效率、责任和人的实际感受一并考虑，技术才能成为改善生活的手段，而非单纯追求速度的目标。', 'Zìdònghuà gōngjù nénggòu chéngdān chóngfù ér jīngquè de gōngzuò, què bù yídìng néng lǐjiě rènwu bèihòu de shèhuì yìyì. Zhēnzhèng yǒuxiào de chuàngxīn, wǎngwǎng láizì jìshù rényuán yǔ shǐyòngzhě chíxù jiāoliú. Zhǐyǒu bǎ xiàolǜ, zérèn hé rén de shíjì gǎnshòu yìbìng kǎolǜ, jìshù cáinéng chéngwéi gǎishàn shēnghuó de shǒuduàn, ér fēi dānchún zhuīqiú sùdù de mùbiāo.', 'Công cụ tự động hóa có thể đảm nhận công việc lặp lại và chính xác, nhưng chưa chắc hiểu ý nghĩa xã hội phía sau nhiệm vụ. Đổi mới thực sự hiệu quả thường đến từ sự trao đổi liên tục giữa người làm kỹ thuật và người sử dụng. Chỉ khi cân nhắc đồng thời hiệu suất, trách nhiệm và trải nghiệm thực tế, công nghệ mới trở thành phương tiện cải thiện đời sống thay vì mục tiêu chỉ chạy theo tốc độ.', 10),
  ('hsk-6', 'hsk6-khong-gian-cong-cong', 'Không gian công cộng', '公共空间', '一座城市的公共空间不只是建筑之间剩下的空地，也体现了居民如何共同生活。若设计只追求视觉效果，却忽略无障碍通道、遮阴和休息座椅，最需要这些设施的人反而难以使用。规划者因此应当从不同群体的日常经验出发，而非仅凭图纸判断空间是否成功。', 'Yí zuò chéngshì de gōnggòng kōngjiān bù zhǐ shì jiànzhù zhījiān shèng xià de kòngdì, yě tǐxiàn le jūmín rúhé gòngtóng shēnghuó. Ruò shèjì zhǐ zhuīqiú shìjué xiàoguǒ, què hūlüè wú zhàng ài tōngdào, zhēyīn hé xiūxi zuòyǐ, zuì xūyào zhèxiē shèshī de rén fǎn ér nányǐ shǐyòng. Guīhuàzhě yīncǐ yīngdāng cóng bùtóng qúntǐ de rìcháng jīngyàn chūfā, ér fēi jǐn píng túzhǐ pànduàn kōngjiān shìfǒu chénggōng.', 'Không gian công cộng không chỉ là phần đất trống giữa các tòa nhà mà còn thể hiện cách cư dân cùng chung sống. Nếu thiết kế chỉ theo đuổi hiệu quả thị giác mà bỏ qua lối đi tiếp cận, bóng râm và ghế nghỉ, những người cần tiện ích ấy nhất lại khó sử dụng. Vì vậy, nhà quy hoạch nên bắt đầu từ trải nghiệm thường ngày của nhiều nhóm cư dân thay vì chỉ nhìn bản vẽ để đánh giá thành công.', 10),
  ('hsk-6', 'hsk6-tri-thuc-va-thong-tin', 'Tri thức và thông tin', '知识与信息', '信息可以在瞬间传播，知识却需要经过筛选、比较和反思才能形成。面对彼此矛盾的说法，若只依据标题作出判断，结论很容易被情绪左右。保持开放并不意味着放弃判断，而是承认自己的理解可能不完整，并愿意随着证据出现而修正观点。', 'Xìnxī kěyǐ zài shùnjiān chuánbō, zhīshi què xūyào jīngguò shāixuǎn, bǐjiào hé fǎnsī cáinéng xíngchéng. Miànduì bǐcǐ máodùn de shuōfǎ, ruò zhǐ yījù biāotí zuò chū pànduàn, jiélùn hěn róngyì bèi qíngxù zuǒyòu. Bǎochí kāifàng bìng bù yìwèizhe fàngqì pànduàn, ér shì chéngrèn zìjǐ de lǐjiě kěnéng bù wánzhěng, bìng yuànyì suí zhe zhèngjù chūxiàn ér xiūzhèng guāndiǎn.', 'Thông tin có thể lan truyền tức thì, còn tri thức cần được sàng lọc, so sánh và suy ngẫm mới hình thành. Trước những lời giải thích trái ngược, nếu chỉ dựa vào tiêu đề để phán đoán, kết luận dễ bị cảm xúc chi phối. Giữ thái độ cởi mở không có nghĩa từ bỏ phán xét, mà là thừa nhận hiểu biết của mình có thể chưa đầy đủ và sẵn lòng điều chỉnh khi có bằng chứng.', 10),
  ('hsk-6', 'hsk6-bao-ton-ngon-ngu', 'Bảo tồn ngôn ngữ', '语言保护', '一种语言的消失，往往不仅意味着词汇不再被使用，也意味着特定的记忆方式和知识体系逐渐失去传承。记录词语固然重要，但若要让语言继续活着，还需要创造让年轻人愿意使用它的环境。保护因此既是保存过去，也是为未来提供选择。', 'Yì zhǒng yǔyán de xiāoshī, wǎngwǎng bùjǐn yìwèizhe cíhuì bú zài bèi shǐyòng, yě yìwèizhe tèdìng de jìyì fāngshì hé zhīshi tǐxì zhújiàn shīqù chuánchéng. Jìlù cíyǔ gùrán zhòngyào, dàn ruò yào ràng yǔyán jìxù huózhe, hái xūyào chuàngzào ràng niánqīng rén yuànyì shǐyòng tā de huánjìng. Bǎohù yīncǐ jì shì bǎocún guòqù, yě shì wèi wèilái tígōng xuǎnzé.', 'Một ngôn ngữ biến mất không chỉ khiến từ vựng ngừng được sử dụng mà còn làm mất dần cách ghi nhớ và hệ thống tri thức đặc thù. Ghi chép từ ngữ tuy quan trọng, nhưng muốn ngôn ngữ tiếp tục sống còn phải tạo môi trường để người trẻ muốn sử dụng nó. Vì vậy, bảo tồn vừa là gìn giữ quá khứ, vừa mở ra lựa chọn cho tương lai.', 10),
  ('hsk-6', 'hsk6-thiet-ke-he-thong-ben-vung', 'Thiết kế hệ thống bền vững', '可持续系统设计', '评价一个系统是否高效，不能只看它在理想条件下的表现，还要考察它面对意外时是否能够维持核心功能。冗余安排有时会被视为浪费，但在关键环节保留替代方案，反而能够降低整体风险。稳健的设计并非拒绝变化，而是让变化不至于造成不可逆的损失。', 'Píngjià yí ge xìtǒng shìfǒu gāoxiào, bùnéng zhǐ kàn tā zài lǐxiǎng tiáojiàn xià de biǎoxiàn, hái yào kǎochá tā miànduì yìwài shí shìfǒu nénggòu wéichí héxīn gōngnéng. Róngyú ānpái yǒushí huì bèi shìwéi làngfèi, dàn zài guānjiàn huánjié bǎoliú tìdài fāngàn, fǎn ér nénggòu jiàngdī zhěngtǐ fēngxiǎn. Wěnjiàn de shèjì bìng fēi jùjué biànhuà, ér shì ràng biànhuà bù zhìyú zàochéng bù kě nì de sǔnshī.', 'Đánh giá một hệ thống có hiệu quả hay không không thể chỉ xem nó hoạt động ra sao trong điều kiện lý tưởng, mà còn phải xem nó có duy trì chức năng cốt lõi khi gặp sự cố không. Phương án dự phòng đôi khi bị coi là lãng phí, nhưng giữ lựa chọn thay thế ở khâu then chốt lại giúp giảm rủi ro tổng thể. Thiết kế vững chắc không từ chối thay đổi mà ngăn thay đổi gây ra tổn thất không thể đảo ngược.', 10),
  ('hsk-6', 'hsk6-doi-thoai-cong-dong', 'Đối thoại cộng đồng', '社区对话', '公共议题通常牵涉多种利益，迅速划分支持者与反对者虽然容易，却会遮蔽问题内部的差异。有效的对话需要先澄清各方担忧，再区分事实、预测与价值判断。即使最后无法达成完全一致，参与者也可能因此找到更公平的折中方案。', 'Gōnggòng yìtí tōngcháng qiānshè duō zhǒng lìyì, xùnsù huàfēn zhīchízhě yǔ fǎnduìzhě suīrán róngyì, què huì zhēbì wèntí nèibù de chāyì. Yǒuxiào de duìhuà xūyào xiān chéngqīng gèfāng dānyōu, zài qūfēn shìshí, yùcè yǔ jiàzhí pànduàn. Jíshǐ zuìhòu wúfǎ dáchéng wánquán yízhì, cānyùzhě yě kěnéng yīncǐ zhǎodào gèng gōngpíng de zhōngzhé fāngàn.', 'Vấn đề công cộng thường liên quan đến nhiều lợi ích. Chia nhanh mọi người thành phe ủng hộ và phản đối tuy dễ nhưng che khuất khác biệt bên trong vấn đề. Đối thoại hiệu quả cần làm rõ mối lo của từng bên, rồi phân biệt sự thật, dự đoán và đánh giá giá trị. Dù cuối cùng không hoàn toàn đồng thuận, người tham gia vẫn có thể tìm được phương án dung hòa công bằng hơn.', 10),
  ('hsk-6', 'hsk6-ky-uc-do-thi', 'Ký ức đô thị', '城市记忆', '城市更新常常以改善居住条件为理由，却也可能使原有社区关系迅速瓦解。保存一栋旧建筑并不足以保存其中的生活记忆，规划还需要关注小店、公共活动和邻里交往。真正有延续性的更新，应当让居民既能享受新的便利，也不必失去对地方的归属感。', 'Chéngshì gēngxīn chángcháng yǐ gǎishàn jūzhù tiáojiàn wéi lǐyóu, què yě kěnéng shǐ yuányǒu shèqū guānxì xùnsù wǎjiě. Bǎocún yí dòng jiù jiànzhù bìng bù zúyǐ bǎocún qízhōng de shēnghuó jìyì, guīhuà hái xūyào guānzhù xiǎodiàn, gōnggòng huódòng hé línlǐ jiāowǎng. Zhēnzhèng yǒu yánxùxìng de gēngxīn, yīngdāng ràng jūmín jì néng xiǎngshòu xīn de biànlì, yě bùbì shīqù duì dìfang de guīshǔgǎn.', 'Cải tạo đô thị thường lấy lý do nâng điều kiện sống, nhưng cũng có thể khiến quan hệ cộng đồng cũ tan rã nhanh chóng. Giữ một tòa nhà cổ chưa đủ bảo tồn ký ức sinh hoạt; quy hoạch còn cần quan tâm cửa tiệm nhỏ, hoạt động chung và giao tiếp láng giềng. Một cuộc cải tạo có tính tiếp nối nên giúp cư dân hưởng tiện ích mới mà không mất cảm giác gắn bó với nơi chốn.', 10),
  ('hsk-6', 'hsk6-danh-gia-tri-tue-nhan-tao', 'Đánh giá trí tuệ nhân tạo', '评估人工智能', '人工智能系统能够从庞大数据中提取规律，但数据本身也可能包含历史偏见。若只以准确率评价模型，某些群体受到的不公平影响就容易被平均数字掩盖。因此，技术评估除了测量性能，还应公开适用范围、错误代价与申诉机制。', 'Réngōng zhìnéng xìtǒng nénggòu cóng pángdà shùjù zhōng tíqǔ guīlǜ, dàn shùjù běnshēn yě kěnéng bāohán lìshǐ piānjiàn. Ruò zhǐ yǐ zhǔnquè lǜ píngjià móxíng, mǒuxiē qúntǐ shòudào de bù gōngpíng yǐngxiǎng jiù róngyì bèi píngjūn shùzì yǎngài. Yīncǐ, jìshù pínggū chúle cèliáng xìngnéng, hái yīng gōngkāi shìyòng fànwéi, cuòwù dàijià yǔ shēnsù jīzhì.', 'Hệ thống trí tuệ nhân tạo có thể rút ra quy luật từ dữ liệu lớn, nhưng dữ liệu cũng có thể chứa định kiến lịch sử. Nếu chỉ đánh giá mô hình bằng độ chính xác, ảnh hưởng bất công lên một số nhóm dễ bị con số trung bình che lấp. Vì vậy, đánh giá công nghệ ngoài đo hiệu năng còn cần công khai phạm vi áp dụng, cái giá của sai sót và cơ chế khiếu nại.', 10),
  ('hsk-6', 'hsk6-khoa-hoc-va-su-khong-chac-chan', 'Khoa học và sự không chắc chắn', '科学与不确定性', '科学结论并非永远不变，而是根据现有证据不断修正。公众有时把这种调整误解为研究者前后矛盾，实际上，能够说明结论的适用条件，正是科学方法区别于绝对断言之处。承认不确定性并不会削弱知识，反而能提醒人们谨慎地使用它。', 'Kēxué jiélùn bìng fēi yǒngyuǎn bú biàn, ér shì gēnjù xiànyǒu zhèngjù bùduàn xiūzhèng. Gōngzhòng yǒushí bǎ zhè zhǒng tiáozhěng wùjiě wéi yánjiūzhě qiánhòu máodùn, shíjì shàng, nénggòu shuōmíng jiélùn de shìyòng tiáojiàn, zhèng shì kēxué fāngfǎ qūbié yú juéduì duànyán zhī chù. Chéngrèn bù quèdìngxìng bìng bú huì xuēruò zhīshi, fǎn ér néng tíxǐng rénmen jǐnshèn de shǐyòng tā.', 'Kết luận khoa học không bất biến mãi mãi mà liên tục được điều chỉnh theo bằng chứng hiện có. Đôi khi công chúng hiểu việc điều chỉnh là nhà nghiên cứu trước sau mâu thuẫn, nhưng khả năng giải thích điều kiện áp dụng chính là điểm khác biệt giữa phương pháp khoa học và khẳng định tuyệt đối. Thừa nhận bất định không làm tri thức yếu đi, mà nhắc ta sử dụng nó thận trọng hơn.', 10)
) AS r (course_slug, slug, title_vi, title_zh, passage_zh, pinyin, translation_vi, est_minutes)
JOIN khoa_hoc c ON c.slug = r.course_slug
ON CONFLICT (slug) DO NOTHING;

COMMIT;